    internal static partial class Converter
    {
        public static readonly JsonSerializerSettings Settings = new JsonSerializerSettings
        {
            MetadataPropertyHandling = MetadataPropertyHandling.Ignore,
            DateParseHandling = DateParseHandling.None,
            Converters =
            {
                EnumValueConverter.Singleton,
                new IsoDateTimeConverter { DateTimeStyles = DateTimeStyles.AssumeUniversal }
            },
        };
    }

    internal class EnumValueConverter : JsonConverter
    {
        public override bool CanConvert(Type t) => t == typeof(EnumValue) || t == typeof(EnumValue?);

        public override object ReadJson(JsonReader reader, Type t, object existingValue, JsonSerializer serializer)
        {
            if (reader.TokenType == JsonToken.Null) return null;
            var value = serializer.Deserialize<string>(reader);
            switch (value)
            {
                case "ready":
                    return EnumValue.Ready;
                case "done":
                    return EnumValue.Done;
            }
            throw new Exception("Cannot unmarshal type EnumValue");
        }

        public override void WriteJson(JsonWriter writer, object untypedValue, JsonSerializer serializer)
        {
            if (untypedValue == null)
            {
                serializer.Serialize(writer, null);
                return;
            }
            var value = (EnumValue)untypedValue;
            switch (value)
            {
                case EnumValue.Ready:
                    serializer.Serialize(writer, "ready");
                    return;
                case EnumValue.Done:
                    serializer.Serialize(writer, "done");
                    return;
            }
            throw new Exception("Cannot marshal type EnumValue");
        }

        public static readonly EnumValueConverter Singleton = new EnumValueConverter();
    }
